def run(job):
    saved=sys.stdout; sys.stdout=sys.stderr
    try:
        return campaign.audit(job)
    except CaptureError:
        return {'error':'capture'}
    except (Invalid,ValueError,TypeError,KeyError,IndexError,RecursionError):
        return {'error':'invalid'}
    finally:
        sys.stdout=saved

